import{_ as n}from"./plugin-vue_export-helper-c27b6911.js";import{o as a,c as s,e}from"./app-4490560f.js";const t={},c=e(`<h1 id="xmake-基于-lua-的跨平台构建工具" tabindex="-1"><a class="header-anchor" href="#xmake-基于-lua-的跨平台构建工具" aria-hidden="true">#</a> xmake（基于 Lua 的跨平台构建工具）</h1><blockquote><p>Homebrew 版本 3.0.5 ｜ 主页：见官方文档 ｜ 安装：<code>brew install xmake</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>xmake 是一个基于 Lua 语言开发的现代化跨平台构建工具，专注于「简单、快速、易用」三大目标。它解决的是传统构建系统（如 Makefile、CMake）语法繁琐、难以维护的问题：你只需编写一份 <code>xmake.lua</code> 描述文件，就能在 Windows、macOS、Linux、iOS、Android 等多个平台上完成编译、链接、打包、运行等全套工作。典型应用场景包括 C/C++ 项目的快速搭建、依赖库的自动下载与集成、以及需要跨平台分发或交叉编译的软件开发。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> xmake

<span class="token comment"># 升级到最新版本</span>
brew upgrade xmake

<span class="token comment"># 卸载</span>
brew uninstall xmake

<span class="token comment"># 查看版本信息</span>
xmake <span class="token parameter variable">--version</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>安装完成后，运行 <code>xmake --version</code> 应能看到类似 <code>xmake v3.0.5+...</code> 的输出。若命令找不到，确认 Homebrew 的 bin 目录（通常是 <code>/opt/homebrew/bin</code> 或 <code>/usr/local/bin</code>）已在 <code>PATH</code> 中。</p><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><table><thead><tr><th>命令</th><th>参数说明</th><th>示例</th></tr></thead><tbody><tr><td><code>xmake create</code></td><td>初始化一个新项目模板，<code>-l</code> 指定语言（c/c++/cuda 等），<code>-t</code> 指定模板类型（console/static/shared）</td><td><code>xmake create -l c++ -t console hello</code></td></tr><tr><td><code>xmake</code></td><td>默认执行编译构建，读取 <code>xmake.lua</code></td><td><code>xmake</code></td></tr><tr><td><code>xmake -r</code></td><td>重新构建（rebuild，强制重编译）</td><td><code>xmake -r</code></td></tr><tr><td><code>xmake run</code></td><td>运行目标程序，可加目标名参数</td><td><code>xmake run hello</code></td></tr><tr><td><code>xmake f</code></td><td>配置/重配置工程（如切换模式、平台）</td><td><code>xmake f -m debug</code></td></tr><tr><td><code>xmake f -p</code></td><td>指定编译平台（linux/macosx/windows/android/ios）</td><td><code>xmake f -p android</code></td></tr><tr><td><code>xmake f -m</code></td><td>指定构建模式（debug/release）</td><td><code>xmake f -m release</code></td></tr><tr><td><code>xmake clean</code></td><td>清理构建产物</td><td><code>xmake clean</code></td></tr><tr><td><code>xmake build</code></td><td>仅构建指定目标，不运行</td><td><code>xmake build hello</code></td></tr><tr><td><code>xmake install</code></td><td>安装产物到指定目录，<code>-o</code> 指定输出路径</td><td><code>xmake install -o /usr/local</code></td></tr><tr><td><code>xmake package</code></td><td>打包发布（生成安装包/归档）</td><td><code>xmake package</code></td></tr><tr><td><code>xmake project</code></td><td>生成 IDE/工具链项目文件</td><td><code>xmake project -k compile_commands</code></td></tr><tr><td><code>xmake l</code> / <code>xmake lua</code></td><td>直接执行内嵌 Lua 脚本</td><td><code>xmake l xmake.lua</code></td></tr><tr><td><code>xmake show</code></td><td>查看当前配置/环境信息</td><td><code>xmake show -l</code></td></tr><tr><td><code>xmake update</code></td><td>从仓库更新 xmake 自身</td><td><code>xmake update</code></td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-快速创建并编译一个-c-控制台程序" tabindex="-1"><a class="header-anchor" href="#示例-1-快速创建并编译一个-c-控制台程序" aria-hidden="true">#</a> 示例 1：快速创建并编译一个 C++ 控制台程序</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 1. 创建项目（生成 main.cpp 和 xmake.lua）</span>
xmake create <span class="token parameter variable">-l</span> c++ <span class="token parameter variable">-t</span> console hello

<span class="token comment"># 2. 进入项目目录</span>
<span class="token builtin class-name">cd</span> hello

<span class="token comment"># 3. 编译（默认 release 模式）</span>
xmake

<span class="token comment"># 4. 运行程序</span>
xmake run
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>执行后终端会输出编译过程，随后 <code>xmake run</code> 打印出 <code>hello xmake!</code>。生成的 <code>xmake.lua</code> 内容大致如下：</p><div class="language-lua line-numbers-mode" data-ext="lua"><pre class="language-lua"><code><span class="token function">add_rules</span><span class="token punctuation">(</span><span class="token string">&quot;mode.debug&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;mode.release&quot;</span><span class="token punctuation">)</span>

<span class="token function">target</span><span class="token punctuation">(</span><span class="token string">&quot;hello&quot;</span><span class="token punctuation">)</span>
    <span class="token function">set_kind</span><span class="token punctuation">(</span><span class="token string">&quot;binary&quot;</span><span class="token punctuation">)</span>
    <span class="token function">add_files</span><span class="token punctuation">(</span><span class="token string">&quot;src/*.cpp&quot;</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-2-切换调试模式并观察优化选项" tabindex="-1"><a class="header-anchor" href="#示例-2-切换调试模式并观察优化选项" aria-hidden="true">#</a> 示例 2：切换调试模式并观察优化选项</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 1. 重新配置为 debug 模式</span>
xmake f <span class="token parameter variable">-m</span> debug

<span class="token comment"># 2. 重新构建</span>
xmake <span class="token parameter variable">-r</span>

<span class="token comment"># 3. 查看链接命令，确认带了 -g 调试信息</span>
xmake <span class="token parameter variable">--verbose</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-3-跨平台编译到-android-需配置-ndk" tabindex="-1"><a class="header-anchor" href="#示例-3-跨平台编译到-android-需配置-ndk" aria-hidden="true">#</a> 示例 3：跨平台编译到 Android（需配置 NDK）</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 1. 配置 Android 平台，指定 NDK 路径</span>
xmake f <span class="token parameter variable">-p</span> android <span class="token parameter variable">--ndk</span><span class="token operator">=</span>/path/to/your/android-ndk <span class="token parameter variable">-m</span> release

<span class="token comment"># 2. 编译</span>
xmake

<span class="token comment"># 3. 打包 APK/AAB 相关的 so 库</span>
xmake package
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-4-自动下载并链接第三方依赖-如-zlib" tabindex="-1"><a class="header-anchor" href="#示例-4-自动下载并链接第三方依赖-如-zlib" aria-hidden="true">#</a> 示例 4：自动下载并链接第三方依赖（如 zlib）</h3><p>在 <code>xmake.lua</code> 中添加如下依赖配置：</p><div class="language-lua line-numbers-mode" data-ext="lua"><pre class="language-lua"><code><span class="token function">add_requires</span><span class="token punctuation">(</span><span class="token string">&quot;zlib&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>system <span class="token operator">=</span> <span class="token keyword">false</span><span class="token punctuation">}</span><span class="token punctuation">)</span>

<span class="token function">target</span><span class="token punctuation">(</span><span class="token string">&quot;hello&quot;</span><span class="token punctuation">)</span>
    <span class="token function">set_kind</span><span class="token punctuation">(</span><span class="token string">&quot;binary&quot;</span><span class="token punctuation">)</span>
    <span class="token function">add_files</span><span class="token punctuation">(</span><span class="token string">&quot;src/*.cpp&quot;</span><span class="token punctuation">)</span>
    <span class="token function">add_packages</span><span class="token punctuation">(</span><span class="token string">&quot;zlib&quot;</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>然后在命令行执行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 首次会从远程仓库自动下载 zlib 并编译集成</span>
xmake f
xmake
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><ol><li><p><strong>多平台一键切换</strong>：使用 <code>xmake f -p</code> 切换平台后，不同平台的配置会缓存到 <code>.xmake</code> 目录中。交叉编译时可用 <code>xmake f --sdk=/path/to/sdk</code> 指定工具链目录，并配合 <code>--arch=</code> 指定架构（如 <code>arm64</code>、<code>x86_64</code>）。若要彻底重置配置（例如换用了不同的 NDK 版本），可删除 <code>.xmake</code> 目录后再 <code>xmake f</code>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">rm</span> <span class="token parameter variable">-rf</span> .xmake
xmake f <span class="token parameter variable">-p</span> android <span class="token parameter variable">--ndk</span><span class="token operator">=</span>/opt/android-ndk <span class="token parameter variable">-a</span> arm64-v8a <span class="token parameter variable">-m</span> release
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>配置文件分层</strong>：核心配置写在项目根目录的 <code>xmake.lua</code>；也可以创建 <code>xmake.rc</code>（顶层全局配置）或每个子目录的 <code>xmake.lua</code> 来分层管理。常用函数如 <code>add_defines()</code> 添加宏定义、<code>add_includedirs()</code> 添加头文件目录、<code>add_linkdirs()</code> 添加链接库目录。在子目录的 <code>xmake.lua</code> 中，用 <code>parent()</code> 表示继承父目录配置：</p><div class="language-lua line-numbers-mode" data-ext="lua"><pre class="language-lua"><code><span class="token comment">-- 根目录 xmake.lua</span>
<span class="token function">set_languages</span><span class="token punctuation">(</span><span class="token string">&quot;c++17&quot;</span><span class="token punctuation">)</span>
<span class="token function">add_defines</span><span class="token punctuation">(</span><span class="token string">&quot;GLOBAL_FLAG&quot;</span><span class="token punctuation">)</span>

<span class="token comment">-- src/xmake.lua 中引用父级</span>
<span class="token function">target</span><span class="token punctuation">(</span><span class="token string">&quot;mylib&quot;</span><span class="token punctuation">)</span>
    <span class="token function">set_kind</span><span class="token punctuation">(</span><span class="token string">&quot;static&quot;</span><span class="token punctuation">)</span>
    <span class="token function">add_files</span><span class="token punctuation">(</span><span class="token string">&quot;*.cpp&quot;</span><span class="token punctuation">)</span>
    <span class="token function">add_includedirs</span><span class="token punctuation">(</span><span class="token string">&quot;$(projectdir)/include&quot;</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>与 CMake 项目集成</strong>：如果已有 CMake 工程，可借助 xmake 的 <code>import(&quot;core.project.project&quot;)</code> 或直接调用系统命令来调用 CMake；反过来 CMake 工程也可通过 <code>xmake</code> 的 CMake generator 生成产物。日常使用中，<code>xmake</code> 与 <code>clangd</code>、<code>ccls</code> 等 IDE 工具可通过生成 <code>compile_commands.json</code>（执行 <code>xmake f --cxxflags=</code> 或 <code>xmake project -k compile_commands</code>）配合实现代码补全：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 生成 compile_commands.json，供 clangd/ccls/VSCode 使用</span>
xmake project <span class="token parameter variable">-k</span> compile_commands
<span class="token comment"># 也可直接生成 CMakeLists.txt / Makefile / vscode / xcode 等</span>
xmake project <span class="token parameter variable">-k</span> cmake
xmake project <span class="token parameter variable">-k</span> makefile
xmake project <span class="token parameter variable">-k</span> vscode
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>环境变量与自动化</strong>：在 CI 中常用 <code>XMAKE_ROOT</code>（xmake 安装根目录）等变量，配合 <code>xmake -P &lt;project&gt;</code> 指定项目目录、<code>xmake --workdir=&lt;dir&gt;</code> 指定工作目录。还可通过 <code>xmake l</code> 直接执行内嵌 Lua 脚本，做自定义构建逻辑扩展。</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 在指定目录构建</span>
xmake <span class="token parameter variable">-P</span> /path/to/project
<span class="token comment"># 覆盖安装根目录（常用于 CI 中安装到固定路径）</span>
<span class="token assign-left variable">XMAKE_ROOT</span><span class="token operator">=</span>/opt/xmake xmake <span class="token parameter variable">-P</span> ./project
<span class="token comment"># 执行一段 Lua 构建逻辑</span>
xmake l <span class="token string">&quot;import(&#39;core.project.config&#39;); print(config.get(&#39;mode&#39;))&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>常用配置函数详解</strong>：掌握以下核心 API 即可覆盖绝大多数项目需求：</p><div class="language-lua line-numbers-mode" data-ext="lua"><pre class="language-lua"><code><span class="token function">set_languages</span><span class="token punctuation">(</span><span class="token string">&quot;c11&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;c++17&quot;</span><span class="token punctuation">)</span>            <span class="token comment">-- 设置语言标准</span>
<span class="token function">set_optimize</span><span class="token punctuation">(</span><span class="token string">&quot;fastest&quot;</span><span class="token punctuation">)</span>                   <span class="token comment">-- 优化级别：none/fast/faster/fastest/smallest</span>
<span class="token function">set_warnings</span><span class="token punctuation">(</span><span class="token string">&quot;all&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;error&quot;</span><span class="token punctuation">)</span>              <span class="token comment">-- 警告级别：none/less/all/more/everything/error</span>
<span class="token function">set_strip</span><span class="token punctuation">(</span><span class="token string">&quot;all&quot;</span><span class="token punctuation">)</span>                          <span class="token comment">-- 剥离符号（发布时减小体积）</span>
<span class="token function">add_cxxflags</span><span class="token punctuation">(</span><span class="token string">&quot;-fno-rtti&quot;</span><span class="token punctuation">)</span>                 <span class="token comment">-- 追加自定义编译选项</span>
<span class="token function">add_ldflags</span><span class="token punctuation">(</span><span class="token string">&quot;-Wl,--gc-sections&quot;</span><span class="token punctuation">)</span>          <span class="token comment">-- 追加自定义链接选项</span>
<span class="token function">add_undefines</span><span class="token punctuation">(</span><span class="token string">&quot;DEBUG&quot;</span><span class="token punctuation">)</span>                    <span class="token comment">-- 取消某个宏定义</span>
<span class="token function">add_defines</span><span class="token punctuation">(</span><span class="token string">&quot;VERSION=1.0&quot;</span><span class="token punctuation">)</span>                <span class="token comment">-- 等价于 -DVERSION=1.0</span>
<span class="token function">add_packages</span><span class="token punctuation">(</span><span class="token string">&quot;zlib&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;openssl&quot;</span><span class="token punctuation">)</span>           <span class="token comment">-- 链接已声明的依赖包</span>
<span class="token function">add_deps</span><span class="token punctuation">(</span><span class="token string">&quot;mylib&quot;</span><span class="token punctuation">)</span>                         <span class="token comment">-- 声明目标间的依赖顺序</span>
<span class="token function">on_load</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span>target<span class="token punctuation">)</span> <span class="token keyword">end</span><span class="token punctuation">)</span>             <span class="token comment">-- 目标加载时的回调</span>
before_build <span class="token operator">/</span> <span class="token function">after_build</span><span class="token punctuation">(</span><span class="token punctuation">...</span><span class="token punctuation">)</span>           <span class="token comment">-- 构建前后钩子</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>条件化与平台差异化配置</strong>：通过 <code>is_plat()</code>、<code>is_arch()</code>、<code>is_mode()</code>、<code>is_os()</code> 做条件分支，一套 <code>xmake.lua</code> 通吃多平台：</p><div class="language-lua line-numbers-mode" data-ext="lua"><pre class="language-lua"><code><span class="token function">target</span><span class="token punctuation">(</span><span class="token string">&quot;app&quot;</span><span class="token punctuation">)</span>
    <span class="token function">set_kind</span><span class="token punctuation">(</span><span class="token string">&quot;binary&quot;</span><span class="token punctuation">)</span>
    <span class="token function">add_files</span><span class="token punctuation">(</span><span class="token string">&quot;src/*.cpp&quot;</span><span class="token punctuation">)</span>
    <span class="token keyword">if</span> <span class="token function">is_plat</span><span class="token punctuation">(</span><span class="token string">&quot;windows&quot;</span><span class="token punctuation">)</span> <span class="token keyword">then</span>
        <span class="token function">add_syslinks</span><span class="token punctuation">(</span><span class="token string">&quot;ws2_32&quot;</span><span class="token punctuation">)</span>
    <span class="token keyword">elseif</span> <span class="token function">is_plat</span><span class="token punctuation">(</span><span class="token string">&quot;linux&quot;</span><span class="token punctuation">)</span> <span class="token keyword">then</span>
        <span class="token function">add_syslinks</span><span class="token punctuation">(</span><span class="token string">&quot;pthread&quot;</span><span class="token punctuation">)</span>
    <span class="token keyword">end</span>
    <span class="token keyword">if</span> <span class="token function">is_mode</span><span class="token punctuation">(</span><span class="token string">&quot;release&quot;</span><span class="token punctuation">)</span> <span class="token keyword">then</span>
        <span class="token function">set_optimize</span><span class="token punctuation">(</span><span class="token string">&quot;fastest&quot;</span><span class="token punctuation">)</span>
        <span class="token function">set_strip</span><span class="token punctuation">(</span><span class="token string">&quot;all&quot;</span><span class="token punctuation">)</span>
    <span class="token keyword">end</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>自定义规则与工具链</strong>：<code>add_rules()</code> 允许复用内置规则（如 <code>qt.static</code>、<code>cuda</code>、<code>swift</code>），也可用 <code>rule()</code> 自定义编译规则；<code>set_toolchains()</code> 可切换到自定义编译器（如 clang、msvc）：</p><div class="language-lua line-numbers-mode" data-ext="lua"><pre class="language-lua"><code><span class="token function">add_rules</span><span class="token punctuation">(</span><span class="token string">&quot;qt.static&quot;</span><span class="token punctuation">)</span>          <span class="token comment">-- 启用 Qt 静态库规则</span>
<span class="token function">set_toolchains</span><span class="token punctuation">(</span><span class="token string">&quot;clang&quot;</span><span class="token punctuation">)</span>         <span class="token comment">-- 切换编译器</span>
<span class="token comment">-- 也可在命令行指定</span>
<span class="token comment">-- xmake f --toolchain=clang</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>多目标与库的组织</strong>：大型项目常拆分为多个 target，用 <code>add_deps()</code> 表达依赖，<code>set_kind(&quot;static&quot;/&quot;shared&quot;/&quot;binary&quot;)</code> 区分产物类型：</p><div class="language-lua line-numbers-mode" data-ext="lua"><pre class="language-lua"><code><span class="token function">target</span><span class="token punctuation">(</span><span class="token string">&quot;core&quot;</span><span class="token punctuation">)</span>
    <span class="token function">set_kind</span><span class="token punctuation">(</span><span class="token string">&quot;static&quot;</span><span class="token punctuation">)</span>
    <span class="token function">add_files</span><span class="token punctuation">(</span><span class="token string">&quot;core/*.cpp&quot;</span><span class="token punctuation">)</span>

<span class="token function">target</span><span class="token punctuation">(</span><span class="token string">&quot;app&quot;</span><span class="token punctuation">)</span>
    <span class="token function">set_kind</span><span class="token punctuation">(</span><span class="token string">&quot;binary&quot;</span><span class="token punctuation">)</span>
    <span class="token function">add_files</span><span class="token punctuation">(</span><span class="token string">&quot;app/*.cpp&quot;</span><span class="token punctuation">)</span>
    <span class="token function">add_deps</span><span class="token punctuation">(</span><span class="token string">&quot;core&quot;</span><span class="token punctuation">)</span>          <span class="token comment">-- app 依赖 core，先构建 core</span>
    <span class="token function">add_linkdirs</span><span class="token punctuation">(</span><span class="token string">&quot;$(buildir)&quot;</span><span class="token punctuation">)</span><span class="token comment">-- 链接到 core 生成的静态库</span>
    <span class="token function">add_links</span><span class="token punctuation">(</span><span class="token string">&quot;core&quot;</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ol><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><ul><li><p><strong>xmake.lua 语法报错</strong>：xmake.lua 是 Lua 脚本，注意括号、引号匹配；常见的坑是漏掉 <code>end</code> 或把 Lua 布尔值写成 <code>True/False</code>（应是小写 <code>true/false</code>）。出错时用 <code>xmake</code> 查看带行号的报错定位。</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 语法错误会提示到具体行号，例如：</span>
<span class="token comment"># error: unexpected symbol near &#39;end&#39;  in xmake.lua:line 12</span>
xmake
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>切换平台/模式后没生效</strong>：切换后务必执行 <code>xmake -r</code>（强制重编译），否则增量构建可能沿用旧配置导致链接错误或路径错乱。若问题依旧，删除 <code>.xmake</code> 缓存目录后重新 <code>xmake f</code>。</p></li><li><p><strong>依赖下载失败</strong>：<code>add_requires</code> 从远程拉取包时可能因网络原因失败，可设置镜像源（如 <code>xmake f --pkg_searchdirs=...</code> 或配置国内镜像），或改用 <code>system=true</code> 使用系统已安装的库。国内网络可配置代理或镜像：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 指定本地包目录</span>
xmake f <span class="token parameter variable">--pkg_searchdirs</span><span class="token operator">=</span>/path/to/packages
<span class="token comment"># 使用代理拉取依赖</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">http_proxy</span><span class="token operator">=</span>http://127.0.0.1:7890
<span class="token builtin class-name">export</span> <span class="token assign-left variable">https_proxy</span><span class="token operator">=</span>http://127.0.0.1:7890
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>头文件找不到/链接失败</strong>：优先检查 <code>add_includedirs</code>、<code>add_linkdirs</code>、<code>add_packages</code> 是否配置完整；交叉编译时尤其要注意工具链与 SDK 路径必须匹配。可用 <code>xmake --verbose</code> 查看实际传给编译器的 <code>-I</code> / <code>-L</code> 参数来诊断。</p></li><li><p><strong>性能与增量构建</strong>：首次全量编译较慢，后续 xmake 支持增量构建与并行编译（默认多核）。若改动头文件导致大量重编译，可考虑合理拆分 target 以减小编译单元规模。控制并行度与输出：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>xmake <span class="token parameter variable">-j</span> <span class="token number">8</span>          <span class="token comment"># 指定并行度</span>
xmake <span class="token parameter variable">-v</span>            <span class="token comment"># 显示详细编译命令</span>
xmake <span class="token parameter variable">-D</span>            <span class="token comment"># 打印更多调试信息</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p><strong>权限问题</strong>：<code>xmake install -o /usr/local</code> 等系统目录安装时需 <code>sudo</code>；交叉编译 Android 时确保 NDK 路径无空格、权限可读。</p></li><li><p><strong>NDK 版本不匹配</strong>：Android 交叉编译报错多因 NDK 路径错误或版本过旧。建议使用官方 <code>r21+</code> 以上版本，并核对 <code>--ndk=</code> 指向的确实是 NDK 根目录（含 <code>toolchains</code>、<code>platforms</code> 子目录），而不是其父目录。</p></li><li><p><strong><code>add_files</code> 通配符与排除</strong>：通配符 <code>*</code> 匹配当前目录，<code>**</code> 递归匹配子目录；可用 <code>{excludes = &quot;...&quot;}</code> 排除不需要的文件：</p><div class="language-lua line-numbers-mode" data-ext="lua"><pre class="language-lua"><code><span class="token function">add_files</span><span class="token punctuation">(</span><span class="token string">&quot;src/**.cpp&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>excludes <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token string">&quot;src/test/**.cpp&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;src/gen/*.cpp&quot;</span><span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></li><li><p><strong>Windows 下路径/编码问题</strong>：<code>add_files</code> 中尽量使用正斜杠 <code>/</code>；若源码含非 UTF-8 编码（如 GBK 注释）可能触发编译器警告，建议统一 UTF-8。</p></li><li><p><strong>安全与发布</strong>：发布 release 时建议开启 <code>set_strip(&quot;all&quot;)</code> 并关闭调试信息，避免符号泄露；对外分发的库注意头文件与 ABI 兼容性，使用 <code>xmake package</code> 生成规范的发布归档。</p></li></ul><h2 id="七、实战-与其它工具搭配与自动化" tabindex="-1"><a class="header-anchor" href="#七、实战-与其它工具搭配与自动化" aria-hidden="true">#</a> 七、实战：与其它工具搭配与自动化</h2><h3 id="_7-1-与-cmake-双向集成" tabindex="-1"><a class="header-anchor" href="#_7-1-与-cmake-双向集成" aria-hidden="true">#</a> 7.1 与 CMake 双向集成</h3><p><strong>从 CMake 迁移到 xmake</strong>：CMake 工程通常有 <code>CMakeLists.txt</code> 和 <code>cmake/</code> 目录。xmake 可直接在 Lua 中调用 CMake 构建已有的 C/C++ 库，也能通过 CMakeLists 生成 CMake 项目让现有 CI 继续使用：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 由 xmake 生成 CMakeLists.txt（适合迁移/供其他工具消费）</span>
xmake project <span class="token parameter variable">-k</span> cmake <span class="token parameter variable">-o</span> ./cmake_out
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>在 xmake 中直接调用 CMake 构建第三方源码</strong>：</p><div class="language-lua line-numbers-mode" data-ext="lua"><pre class="language-lua"><code><span class="token comment">-- 用 os.exec 在配置阶段调用 cmake 构建一个第三方库</span>
<span class="token function">after_configure</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    os<span class="token punctuation">.</span><span class="token function">exec</span><span class="token punctuation">(</span><span class="token string">&quot;cmake -S 3rd/lib -B build_3rd -DCMAKE_BUILD_TYPE=Release&quot;</span><span class="token punctuation">)</span>
    os<span class="token punctuation">.</span><span class="token function">exec</span><span class="token punctuation">(</span><span class="token string">&quot;cmake --build build_3rd -j 4&quot;</span><span class="token punctuation">)</span>
<span class="token keyword">end</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-2-与-makefile-ninja-搭配" tabindex="-1"><a class="header-anchor" href="#_7-2-与-makefile-ninja-搭配" aria-hidden="true">#</a> 7.2 与 Makefile / Ninja 搭配</h3><p>xmake 内置构建引擎，默认不需要外部构建器，但它也可以生成并消费 <code>Makefile</code> 和 <code>ninja</code>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 生成 Makefile 供传统 Make 流程使用</span>
xmake project <span class="token parameter variable">-k</span> makefile
<span class="token comment"># 生成 ninja 构建文件</span>
xmake project <span class="token parameter variable">-k</span> ninja
<span class="token comment"># 与 ninja 结合控制并行度</span>
xmake project <span class="token parameter variable">-k</span> ninja <span class="token operator">&amp;&amp;</span> ninja <span class="token parameter variable">-j</span> <span class="token number">8</span> <span class="token parameter variable">-C</span> ./build
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>若项目里已有 <code>Makefile</code>，可在 xmake 的钩子里调用它：</p><div class="language-lua line-numbers-mode" data-ext="lua"><pre class="language-lua"><code><span class="token function">before_build</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span>target<span class="token punctuation">)</span>
    os<span class="token punctuation">.</span><span class="token function">exec</span><span class="token punctuation">(</span><span class="token string">&quot;make -C legacy clean all&quot;</span><span class="token punctuation">)</span>
<span class="token keyword">end</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-3-与-git-集成-忽略构建产物" tabindex="-1"><a class="header-anchor" href="#_7-3-与-git-集成-忽略构建产物" aria-hidden="true">#</a> 7.3 与 Git 集成（忽略构建产物）</h3><p>在项目根目录添加 <code>.gitignore</code>，避免把 <code>.xmake</code> 缓存和 <code>build</code> 目录提交到仓库：</p><div class="language-gitignore line-numbers-mode" data-ext="gitignore"><pre class="language-gitignore"><code><span class="token entry string">.xmake<span class="token punctuation">/</span></span>
<span class="token entry string">build<span class="token punctuation">/</span></span>
<span class="token entry string"><span class="token operator">*</span>.o</span>
<span class="token entry string"><span class="token operator">*</span>.obj</span>
<span class="token entry string">compile_commands.json</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-4-makefile-脚本自动化" tabindex="-1"><a class="header-anchor" href="#_7-4-makefile-脚本自动化" aria-hidden="true">#</a> 7.4 Makefile 脚本自动化</h3><p>写一个顶层 <code>Makefile</code> 把 xmake 命令封装成常用目标，方便团队统一入口：</p><div class="language-makefile line-numbers-mode" data-ext="makefile"><pre class="language-makefile"><code><span class="token builtin-target builtin">.PHONY</span><span class="token punctuation">:</span> all config build run clean install package test

<span class="token target symbol">all</span><span class="token punctuation">:</span> build

<span class="token target symbol">config</span><span class="token punctuation">:</span>
	xmake f -m release

<span class="token target symbol">build</span><span class="token punctuation">:</span> config
	xmake

<span class="token target symbol">run</span><span class="token punctuation">:</span> build
	xmake run

<span class="token target symbol">test</span><span class="token punctuation">:</span>
	xmake run test

<span class="token target symbol">clean</span><span class="token punctuation">:</span>
	xmake clean

<span class="token target symbol">install</span><span class="token punctuation">:</span>
	sudo xmake install -o /usr/local

<span class="token target symbol">package</span><span class="token punctuation">:</span> build
	xmake package
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-5-ci-集成-github-actions-gitlab-ci" tabindex="-1"><a class="header-anchor" href="#_7-5-ci-集成-github-actions-gitlab-ci" aria-hidden="true">#</a> 7.5 CI 集成（GitHub Actions / GitLab CI）</h3><p><strong>GitHub Actions</strong> 示例：在 <code>.github/workflows/build.yml</code> 中配置多平台矩阵构建：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">name</span><span class="token punctuation">:</span> build
<span class="token key atrule">on</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>push<span class="token punctuation">,</span> pull_request<span class="token punctuation">]</span>
<span class="token key atrule">jobs</span><span class="token punctuation">:</span>
  <span class="token key atrule">build</span><span class="token punctuation">:</span>
    <span class="token key atrule">strategy</span><span class="token punctuation">:</span>
      <span class="token key atrule">matrix</span><span class="token punctuation">:</span>
        <span class="token key atrule">os</span><span class="token punctuation">:</span> <span class="token punctuation">[</span>ubuntu<span class="token punctuation">-</span>latest<span class="token punctuation">,</span> macos<span class="token punctuation">-</span>latest<span class="token punctuation">,</span> windows<span class="token punctuation">-</span>latest<span class="token punctuation">]</span>
    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> $<span class="token punctuation">{</span><span class="token punctuation">{</span> matrix.os <span class="token punctuation">}</span><span class="token punctuation">}</span>
    <span class="token key atrule">steps</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/checkout@v4
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Install xmake
        <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
          curl -fsSL https://xmake.io/shget.text | bash
          echo &quot;$HOME/.xmake&quot; &gt;&gt; $GITHUB_PATH</span>
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Configure
        <span class="token key atrule">run</span><span class="token punctuation">:</span> xmake f <span class="token punctuation">-</span>m release
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Build
        <span class="token key atrule">run</span><span class="token punctuation">:</span> xmake
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Run tests
        <span class="token key atrule">run</span><span class="token punctuation">:</span> xmake run test
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Package
        <span class="token key atrule">run</span><span class="token punctuation">:</span> xmake package
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>GitLab CI</strong>（<code>.gitlab-ci.yml</code>）：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token key atrule">image</span><span class="token punctuation">:</span> ubuntu<span class="token punctuation">:</span><span class="token number">22.04</span>
<span class="token key atrule">build</span><span class="token punctuation">:</span>
  <span class="token key atrule">script</span><span class="token punctuation">:</span>
    <span class="token punctuation">-</span> apt<span class="token punctuation">-</span>get update <span class="token important">&amp;&amp;</span> apt<span class="token punctuation">-</span>get install <span class="token punctuation">-</span>y build<span class="token punctuation">-</span>essential curl
    <span class="token punctuation">-</span> curl <span class="token punctuation">-</span>fsSL https<span class="token punctuation">:</span>//xmake.io/shget.text <span class="token punctuation">|</span> bash
    <span class="token punctuation">-</span> export PATH=&quot;$HOME/.xmake<span class="token punctuation">:</span>$PATH&quot;
    <span class="token punctuation">-</span> xmake f <span class="token punctuation">-</span>m release
    <span class="token punctuation">-</span> xmake
  <span class="token key atrule">artifacts</span><span class="token punctuation">:</span>
    <span class="token key atrule">paths</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> build/
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-6-批量处理与多配置构建" tabindex="-1"><a class="header-anchor" href="#_7-6-批量处理与多配置构建" aria-hidden="true">#</a> 7.6 批量处理与多配置构建</h3><p>一次性对多个平台/架构组合执行全流程：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token keyword">for</span> <span class="token for-or-select variable">target</span> <span class="token keyword">in</span> <span class="token string">&quot;macosx arm64&quot;</span> <span class="token string">&quot;macosx x86_64&quot;</span> <span class="token string">&quot;android arm64-v8a&quot;</span><span class="token punctuation">;</span> <span class="token keyword">do</span>
  <span class="token builtin class-name">set</span> -- <span class="token variable">$target</span>
  xmake f <span class="token parameter variable">-p</span> <span class="token variable">$1</span> <span class="token parameter variable">-a</span> <span class="token variable">$2</span> <span class="token parameter variable">-m</span> release <span class="token parameter variable">--clean</span>
  xmake
  xmake package <span class="token parameter variable">-o</span> dist/<span class="token variable">$1</span>-<span class="token variable">$2</span>
<span class="token keyword">done</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>配合 <code>xmake show</code> 快速确认当前生效的工具链与平台信息：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>xmake show <span class="token parameter variable">-l</span>          <span class="token comment"># 列出所有 target</span>
xmake show <span class="token parameter variable">-p</span>          <span class="token comment"># 显示当前平台</span>
xmake show <span class="token parameter variable">--toolchain</span> <span class="token comment"># 显示当前工具链</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-7-生产级实践建议" tabindex="-1"><a class="header-anchor" href="#_7-7-生产级实践建议" aria-hidden="true">#</a> 7.7 生产级实践建议</h3><ul><li><strong>版本固化</strong>：在 CI 与团队间统一 xmake 版本，避免行为差异，可用 <code>xmake update</code> 或锁在 Docker 镜像里。</li><li><strong>依赖锁定</strong>：对第三方依赖明确指定版本，保证可复现构建：<code>add_requires(&quot;zlib 1.3.1&quot;)</code>。</li><li><strong>产物路径统一</strong>：用 <code>set_targetdir(&quot;$(buildir)/$(plat)/$(arch)/$(mode)&quot;)</code> 让不同平台/架构/模式的产物互不覆盖，便于归档与发布。</li><li><strong>测试纳入构建</strong>：把单元测试写成独立 target 并在 CI 中运行，用 <code>xmake run test</code> 一键触发，形成「构建 → 测试 → 打包」的完整流水线。</li><li><strong>缓存复用</strong>：在 CI 中缓存 <code>~/.xmake/packages</code> 目录，可显著加快依赖安装；本地多次切换配置时保留 <code>.xmake</code> 目录能利用增量缓存。</li></ul>`,56),o=[c];function i(l,p){return a(),s("div",null,o)}const r=n(t,[["render",i],["__file","xmake.html.vue"]]);export{r as default};
